<?php require 'config.php'; $page_title='Login — HOSTNEIL'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');$ok=false;foreach(store_read()['users'] as $u)if($u['email']===$email&&password_verify($pass,$u['password_hash']))$ok=true;if($ok){session_regenerate_id(true);$_SESSION['user_email']=$email;redirect('dashboard.php');}else $err='Invalid email or password.';} require 'includes/header.php'; ?><section class="section"><form class="formbox" method="post"><span class="eyebrow">CUSTOMER AREA</span><h2>Log in</h2><?php if($err): ?><div class="flash error"><?= h($err) ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn full">Log in</button><p class="small">New customer? <a class="accent" href="register.php">Create an account</a></p></form></section><?php require 'includes/footer.php'; ?>